-- Контент перенесённых страниц (редактор блоков): policy, terms, cookie-policy, about, contacts, partners
-- ВАЖНО: NO_BACKSLASH_ESCAPES нужен, чтобы MySQL не интерпретировал \" в JSON
-- как экранированную кавычку (иначе JSON ломается). Применять после schema.sql и seed_pages.sql.
SET NAMES utf8mb4;
SET CHARACTER SET utf8mb4;
SET SESSION sql_mode = CONCAT(@@sql_mode, ',NO_BACKSLASH_ESCAPES');

USE it_services;

-- policy
INSERT INTO pages (slug, title, meta_title, meta_description, content, status)
SELECT 'policy', 'Политика конфиденциальности', 'Политика конфиденциальности — обработка персональных данных', 'Политика конфиденциальности сайта: какие персональные данные обрабатываются, цели и правовые основания, cookie, права пользователя, сроки хранения.', '[{"id":"sec-1-w1ffv","columns":1,"gap":"normal","background":"default","align":"top","cols":[{"id":"col-2-mfr91","blocks":[{"type":"text","text":"Последнее обновление: 14 сентября 2026 года","align":"left"},{"type":"heading","text":"1. Общие положения","level":"h2","align":"left"},{"type":"text","text":"Настоящая Политика конфиденциальности (далее — Политика) определяет порядок обработки и защиты персональных данных посетителей и пользователей сайта (далее — Пользователь) в соответствии с Федеральным законом от 27.07.2006 № 152-ФЗ «О персональных данных», Федеральным законом от 27.07.2006 № 149-ФЗ «Об информации, информационных технологиях и о защите информации» и иными нормативными правовыми актами Российской Федерации.","align":"left"},{"type":"text","text":"Используя сайт, заполняя формы заявок и обращений, Пользователь выражает согласие с условиями настоящей Политики и даёт согласие на обработку своих персональных данных способами, предусмотренными Политикой. Если Пользователь не согласен с условиями Политики, он должен прекратить использование сайта.","align":"left"},{"type":"heading","text":"2. Оператор персональных данных","level":"h2","align":"left"},{"type":"text","text":"Оператором персональных данных является исполнитель ИТ-услуг — Литвинов Антон (г. Краснодар). Контактные данные для вопросов, связанных с обработкой персональных данных: <a href=\"mailto:hello@example.ru\">hello@example.ru</a>.","align":"left"},{"type":"heading","text":"3. Состав обрабатываемых данных","level":"h2","align":"left"},{"type":"text","text":"При заполнении форм на сайте обрабатываются следующие персональные данные:","align":"left"},{"type":"list","items":["имя;","номер телефона;","адрес электронной почты (при указании);","контакт мессенджера (при указании);","содержание обращения (сообщение);","сведения о выбранной услуге и странице сайта;","источник перехода на сайт (UTM-метки)."],"ordered":false},{"type":"heading","text":"4. Цели обработки персональных данных","level":"h2","align":"left"},{"type":"text","text":"Персональные данные обрабатываются в следующих целях:","align":"left"},{"type":"list","items":["связь с Пользователем по его обращению, консультирование и подготовка коммерческого предложения;","заключение и исполнение договоров;","улучшение качества работы сайта и сервисов, статистический анализ посещаемости;","предотвращение мошенничества и злоупотреблений."],"ordered":false},{"type":"heading","text":"5. Правовые основания обработки","level":"h2","align":"left"},{"type":"text","text":"Обработка персональных данных осуществляется на основании:","align":"left"},{"type":"list","items":["согласия Пользователя на обработку персональных данных, которое даётся при заполнении форм;","заключения и исполнения договора, стороной которого является Пользователь;","законных интересов Оператора (статья 6 Федерального закона № 152-ФЗ)."],"ordered":false},{"type":"heading","text":"6. Использование файлов cookie","level":"h2","align":"left"},{"type":"text","text":"Сайт использует файлы cookie (куки) — небольшие файлы, сохраняемые в браузере Пользователя. Они используются для:","align":"left"},{"type":"list","items":["корректной работы сайта и запоминания предпочтений;","сбора обезличенной статистики посещаемости (например, Яндекс.Метрика)."],"ordered":false},{"type":"text","text":"Пользователь может отключить использование cookie в настройках своего браузера. Отключение cookie может повлиять на работу отдельных функций сайта.","align":"left"},{"type":"heading","text":"7. Порядок и условия обработки персональных данных","level":"h2","align":"left"},{"type":"text","text":"Обработка персональных данных осуществляется с использованием средств автоматизации и без их использования. Оператор принимает необходимые правовые, организационные и технические меры для защиты персональных данных от неправомерного или случайного доступа, уничтожения, изменения, блокирования, копирования, предоставления, распространения, а также от иных неправомерных действий.","align":"left"},{"type":"text","text":"Персональные данные не передаются третьим лицам, за исключением случаев, предусмотренных законодательством Российской Федерации.","align":"left"},{"type":"heading","text":"8. Сроки обработки и хранения","level":"h2","align":"left"},{"type":"text","text":"Персональные данные обрабатываются и хранятся в течение срока, необходимого для целей обработки, либо до момента отзыва согласия Пользователем, если иное не предусмотрено законодательством Российской Федерации.","align":"left"},{"type":"heading","text":"9. Права Пользователя","level":"h2","align":"left"},{"type":"text","text":"Пользователь вправе:","align":"left"},{"type":"list","items":["получать информацию, касающуюся обработки его персональных данных;","требовать уточнения, блокирования или уничтожения своих персональных данных;","отозвать согласие на обработку персональных данных;","обжаловать действия или бездействие Оператора в уполномоченный орган по защите прав субъектов персональных данных (Роскомнадзор) или в судебном порядке."],"ordered":false},{"type":"text","text":"Для реализации своих прав Пользователь может направить запрос на почту <a href=\"mailto:hello@example.ru\">hello@example.ru</a>.","align":"left"},{"type":"heading","text":"10. Заключительные положения","level":"h2","align":"left"},{"type":"text","text":"Оператор вправе вносить изменения в настоящую Политику. Актуальная редакция Политики всегда размещена на этой странице. Продолжение использования сайта после внесения изменений означает согласие Пользователя с новой редакцией Политики.","align":"left"}]}]}]', 'published'
WHERE NOT EXISTS (SELECT 1 FROM pages WHERE slug = 'policy');

