-- terms
INSERT INTO pages (slug, title, meta_title, meta_description, content, status)
SELECT 'terms', 'Пользовательское соглашение', 'Пользовательское соглашение — условия использования сайта', 'Пользовательское соглашение: предмет, условия оказания услуг, права и обязанности пользователя, интеллектуальная собственность и ответственность.', '[{"id":"sec-3-azzlw","columns":1,"gap":"normal","background":"default","align":"top","cols":[{"id":"col-4-r42mb","blocks":[{"type":"text","text":"Последнее обновление: 14 сентября 2026 года","align":"left"},{"type":"heading","text":"1. Общие положения","level":"h2","align":"left"},{"type":"text","text":"Настоящее Пользовательское соглашение (далее — Соглашение) регулирует отношения между исполнителем ИТ-услуг Литвиновым Антоном (далее — Исполнитель) и пользователем сайта (далее — Пользователь), определяет условия использования сайта, размещённой на нём информации, а также порядок оказания услуг.","align":"left"},{"type":"text","text":"Используя сайт, Пользователь подтверждает, что ознакомился с условиями настоящего Соглашения и Политикой конфиденциальности, полностью понимает и принимает их. Если Пользователь не согласен с условиями, он обязан прекратить использование сайта.","align":"left"},{"type":"heading","text":"2. Предмет соглашения","level":"h2","align":"left"},{"type":"text","text":"Сайт носит информационный характер и предназначен для ознакомления с услугами Исполнителя: разработка и сопровождение сайтов, внедрение CRM-систем, работы с базами данных, разработка корпоративного софта, интеграции и автоматизация бизнес-процессов. Размещённая на сайте информация не является публичной офертой (статья 437 Гражданского кодекса РФ), если иное прямо не указано.","align":"left"},{"type":"heading","text":"3. Условия оказания услуг","level":"h2","align":"left"},{"type":"text","text":"Услуги оказываются на основании отдельного договора или иного соглашения, заключаемого между Исполнителем и Заказчиком. Существенные условия (состав работ, сроки, стоимость) фиксируются сторонами до начала оказания услуг и не могут быть изменены в одностороннем порядке.","align":"left"},{"type":"heading","text":"4. Права и обязанности Пользователя","level":"h2","align":"left"},{"type":"list","items":["Пользователь обязуется предоставлять достоверные данные при заполнении форм;","Пользователь обязуется не использовать сайт для размещения недостоверной информации, спама, вредоносных материалов;","Пользователь не вправе копировать, воспроизводить или распространять материалы сайта без согласия Исполнителя;","Пользователь вправе обращаться к Исполнителю через формы связи, указанные на сайте."],"ordered":false},{"type":"heading","text":"5. Интеллектуальная собственность","level":"h2","align":"left"},{"type":"text","text":"Все материалы сайта (тексты, изображения, логотипы, дизайн) являются объектами интеллектуальной собственности Исполнителя либо используются им на законных основаниях. Использование материалов сайта без согласия правообладателя не допускается.","align":"left"},{"type":"heading","text":"6. Ответственность","level":"h2","align":"left"},{"type":"text","text":"Исполнитель прилагает разумные усилия для обеспечения корректной работы сайта, однако не гарантирует бесперебойную работу и не несёт ответственности за перерывы в доступе, вызванные техническими сбоями, действиями третьих лиц или обстоятельствами непреодолимой силы. Информация на сайте предоставляется «как есть» и может быть изменена Исполнителем без предварительного уведомления.","align":"left"},{"type":"heading","text":"7. Обработка персональных данных","level":"h2","align":"left"},{"type":"text","text":"Обработка персональных данных Пользователей осуществляется в соответствии с Политикой конфиденциальности, размещённой на сайте. Используя формы обратной связи, Пользователь даёт согласие на обработку своих персональных данных.","align":"left"},{"type":"heading","text":"8. Заключительные положения","level":"h2","align":"left"},{"type":"text","text":"Исполнитель вправе вносить изменения в настоящее Соглашение. Актуальная редакция всегда размещена на этой странице. Продолжение использования сайта после изменений означает согласие с новой редакцией. К отношениям сторон применяется законодательство Российской Федерации.","align":"left"}]}]}]', 'published'
WHERE NOT EXISTS (SELECT 1 FROM pages WHERE slug = 'terms');

UPDATE pages SET
  title = 'Пользовательское соглашение',
  meta_title = 'Пользовательское соглашение — условия использования сайта',
  meta_description = 'Пользовательское соглашение: предмет, условия оказания услуг, права и обязанности пользователя, интеллектуальная собственность и ответственность.',
  content = '[{"id":"sec-3-azzlw","columns":1,"gap":"normal","background":"default","align":"top","cols":[{"id":"col-4-r42mb","blocks":[{"type":"text","text":"Последнее обновление: 14 сентября 2026 года","align":"left"},{"type":"heading","text":"1. Общие положения","level":"h2","align":"left"},{"type":"text","text":"Настоящее Пользовательское соглашение (далее — Соглашение) регулирует отношения между исполнителем ИТ-услуг Литвиновым Антоном (далее — Исполнитель) и пользователем сайта (далее — Пользователь), определяет условия использования сайта, размещённой на нём информации, а также порядок оказания услуг.","align":"left"},{"type":"text","text":"Используя сайт, Пользователь подтверждает, что ознакомился с условиями настоящего Соглашения и Политикой конфиденциальности, полностью понимает и принимает их. Если Пользователь не согласен с условиями, он обязан прекратить использование сайта.","align":"left"},{"type":"heading","text":"2. Предмет соглашения","level":"h2","align":"left"},{"type":"text","text":"Сайт носит информационный характер и предназначен для ознакомления с услугами Исполнителя: разработка и сопровождение сайтов, внедрение CRM-систем, работы с базами данных, разработка корпоративного софта, интеграции и автоматизация бизнес-процессов. Размещённая на сайте информация не является публичной офертой (статья 437 Гражданского кодекса РФ), если иное прямо не указано.","align":"left"},{"type":"heading","text":"3. Условия оказания услуг","level":"h2","align":"left"},{"type":"text","text":"Услуги оказываются на основании отдельного договора или иного соглашения, заключаемого между Исполнителем и Заказчиком. Существенные условия (состав работ, сроки, стоимость) фиксируются сторонами до начала оказания услуг и не могут быть изменены в одностороннем порядке.","align":"left"},{"type":"heading","text":"4. Права и обязанности Пользователя","level":"h2","align":"left"},{"type":"list","items":["Пользователь обязуется предоставлять достоверные данные при заполнении форм;","Пользователь обязуется не использовать сайт для размещения недостоверной информации, спама, вредоносных материалов;","Пользователь не вправе копировать, воспроизводить или распространять материалы сайта без согласия Исполнителя;","Пользователь вправе обращаться к Исполнителю через формы связи, указанные на сайте."],"ordered":false},{"type":"heading","text":"5. Интеллектуальная собственность","level":"h2","align":"left"},{"type":"text","text":"Все материалы сайта (тексты, изображения, логотипы, дизайн) являются объектами интеллектуальной собственности Исполнителя либо используются им на законных основаниях. Использование материалов сайта без согласия правообладателя не допускается.","align":"left"},{"type":"heading","text":"6. Ответственность","level":"h2","align":"left"},{"type":"text","text":"Исполнитель прилагает разумные усилия для обеспечения корректной работы сайта, однако не гарантирует бесперебойную работу и не несёт ответственности за перерывы в доступе, вызванные техническими сбоями, действиями третьих лиц или обстоятельствами непреодолимой силы. Информация на сайте предоставляется «как есть» и может быть изменена Исполнителем без предварительного уведомления.","align":"left"},{"type":"heading","text":"7. Обработка персональных данных","level":"h2","align":"left"},{"type":"text","text":"Обработка персональных данных Пользователей осуществляется в соответствии с Политикой конфиденциальности, размещённой на сайте. Используя формы обратной связи, Пользователь даёт согласие на обработку своих персональных данных.","align":"left"},{"type":"heading","text":"8. Заключительные положения","level":"h2","align":"left"},{"type":"text","text":"Исполнитель вправе вносить изменения в настоящее Соглашение. Актуальная редакция всегда размещена на этой странице. Продолжение использования сайта после изменений означает согласие с новой редакцией. К отношениям сторон применяется законодательство Российской Федерации.","align":"left"}]}]}]',
  updated_at = NOW()
WHERE slug = 'terms';

-- cookie-policy
INSERT INTO pages (slug, title, meta_title, meta_description, content, status)
SELECT 'cookie-policy', 'Политика обработки файлов cookie', 'Политика обработки файлов cookie — рекомендательные технологии', 'Какие файлы cookie использует сайт, зачем они нужны, срок хранения, как управлять cookie и как даётся согласие на их обработку.', '[{"id":"sec-5-dhdb6","columns":1,"gap":"normal","background":"default","align":"top","cols":[{"id":"col-6-zakt4","blocks":[{"type":"text","text":"Последнее обновление: 15 сентября 2026 года","align":"left"},{"type":"heading","text":"1. Что такое cookie","level":"h2","align":"left"},{"type":"text","text":"Файлы cookie (куки) — это небольшие текстовые файлы, которые сохраняются на вашем устройстве (компьютере, планшете, смартфоне) при посещении сайта. Они позволяют сайту запоминать ваши действия и предпочтения на протяжении определённого времени.","align":"left"},{"type":"heading","text":"2. Какие cookie мы используем","level":"h2","align":"left"},{"type":"list","items":["<strong>Технические (обязательные)</strong> — необходимы для корректной работы сайта: запоминание согласия на обработку cookie, поддержание сессии, защита от CSRF-атак. Без них сайт не может работать полноценно.","<strong>Аналитические</strong> — помогают понимать, как посетители пользуются сайтом (Яндекс.Метрика): какие страницы открывают, сколько времени проводят, с каких устройств заходят. Эти данные обезличены и используются для улучшения сервиса.","<strong>Рекомендательные</strong> — применяются для подбора и показа релевантного контента и предложений с учётом ваших предпочтений и поведения на сайте."],"ordered":false},{"type":"heading","text":"3. Зачем мы собираем cookie","level":"h2","align":"left"},{"type":"text","text":"Мы собираем файлы cookie и применяем рекомендательные технологии для того, чтобы:","align":"left"},{"type":"list","items":["обеспечить корректную работу и безопасность сайта;","анализировать посещаемость и поведение пользователей (обезличенно);","улучшать удобство и содержание сайта;","показывать более релевантные материалы и предложения."],"ordered":false},{"type":"heading","text":"4. Срок хранения","level":"h2","align":"left"},{"type":"text","text":"Срок хранения cookie зависит от их типа. Сессионные cookie удаляются после закрытия браузера. Постоянные cookie могут храниться на вашем устройстве до одного года или до момента, пока вы их не удалите.","align":"left"},{"type":"heading","text":"5. Как управлять cookie","level":"h2","align":"left"},{"type":"text","text":"Вы можете отключить или удалить файлы cookie в настройках вашего браузера. Обратите внимание: после отключения cookie некоторые функции сайта могут работать некорректно (например, запоминание вашего выбора или сохранение заявок).","align":"left"},{"type":"text","text":"Для управления cookie в популярных браузерах используйте разделы настроек «Конфиденциальность» или «Cookies». Также можно воспользоваться инструментами для блокировки аналитических систем, например, официальным расширением Яндекс.Метрики.","align":"left"},{"type":"heading","text":"6. Согласие на обработку","level":"h2","align":"left"},{"type":"text","text":"При первом посещении сайта отображается уведомление о сборе файлов cookie. Нажимая кнопку «Принять», вы соглашаетесь на использование cookie и применение рекомендательных технологий в соответствии с настоящей Политикой. Продолжение использования сайта без нажатия кнопки «Принять» также означает согласие на обработку технически необходимых cookie.","align":"left"},{"type":"heading","text":"7. Контакты","level":"h2","align":"left"},{"type":"text","text":"По вопросам, связанным с обработкой файлов cookie и персональных данных, вы можете обратиться через форму обратной связи на странице «Контакты» или по контактам, указанным в <a href=\"/policy\">Политике конфиденциальности</a>.","align":"left"}]}]}]', 'published'
WHERE NOT EXISTS (SELECT 1 FROM pages WHERE slug = 'cookie-policy');

